const OFFLINE_CACHE_KEY="culture_offline_cache_v1",OFFLINE_QUEUE_KEY="culture_offline_attendance_v1",OFFLINE_NOTES_KEY="culture_offline_calendar_notes_v1";
const stored=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
const saveStored=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{}};
const cachePut=(key,value)=>{const cache=stored(OFFLINE_CACHE_KEY,{});cache[key]={saved_at:Date.now(),value};saveStored(OFFLINE_CACHE_KEY,cache);};
const cacheGet=key=>stored(OFFLINE_CACHE_KEY,{})[key]?.value??null;
const isConnectionError=error=>!navigator.onLine||error instanceof TypeError||/network|fetch|internet|offline/i.test(String(error?.message||error));
function updateConnectionStatus(){const el=$("#connection-status");if(!el)return;const pending=stored(OFFLINE_QUEUE_KEY,[]).length,offline=!navigator.onLine;el.textContent=offline?`SIN CONEXIÓN${pending?` · ${pending} PENDIENTE${pending===1?"":"S"}`:""}`:pending?`SINCRONIZACIÓN PENDIENTE · ${pending}`:"EN LÍNEA";el.classList.toggle("offline",offline||Boolean(pending));}
function enqueueAttendance(payload){const queue=stored(OFFLINE_QUEUE_KEY,[]),key=`${payload.p_activity_id}|${payload.p_journey_date}`,entry={...payload,queued_at:Date.now()};const existing=queue.findIndex(item=>`${item.p_activity_id}|${item.p_journey_date}`===key);if(existing>=0)queue[existing]=entry;else queue.push(entry);saveStored(OFFLINE_QUEUE_KEY,queue);updateConnectionStatus();}
function pendingAttendance(activityId,date){return stored(OFFLINE_QUEUE_KEY,[]).filter(item=>Number(item.p_activity_id)===Number(activityId)&&item.p_journey_date===date).at(-1)||null;}
async function saveAttendanceWithOfflineQueue(payload){if(!navigator.onLine){enqueueAttendance(payload);return {queued:true};}const {error}=await db.rpc("save_activity_journey",payload);if(!error)return {queued:false};if(isConnectionError(error)){enqueueAttendance(payload);return {queued:true};}return {error};}
async function syncOfflineAttendance(){if(!navigator.onLine||!state.session)return;const queue=stored(OFFLINE_QUEUE_KEY,[]);if(!queue.length){updateConnectionStatus();return;}const remaining=[];let synced=0;for(const payload of queue){const {error}=await db.rpc("save_activity_journey",payload);if(error){remaining.push(payload);continue;}synced++;}saveStored(OFFLINE_QUEUE_KEY,remaining);updateConnectionStatus();if(synced)toast(`${synced} ASISTENCIA${synced===1?"":"S"} SINCRONIZADA${synced===1?"":"S"}.`);if(remaining.length)toast("ALGUNAS ASISTENCIAS SIGUEN PENDIENTES DE SINCRONIZACIÓN.","error");}
async function saveCalendarNote(body){const payload={body:body.trim()};if(!navigator.onLine){const queue=stored(OFFLINE_NOTES_KEY,[]);queue.push({...payload,queued_at:Date.now()});saveStored(OFFLINE_NOTES_KEY,queue);return {queued:true};}const {error}=await db.from("calendar_annotations").insert(payload);if(!error)return {queued:false};if(isConnectionError(error)){const queue=stored(OFFLINE_NOTES_KEY,[]);queue.push({...payload,queued_at:Date.now()});saveStored(OFFLINE_NOTES_KEY,queue);return {queued:true};}return {error};}
async function syncCalendarNotes(){if(!navigator.onLine||!state.session)return;const queue=stored(OFFLINE_NOTES_KEY,[]),remaining=[];for(const note of queue){const {error}=await db.from("calendar_annotations").insert({body:note.body});if(error)remaining.push(note);}saveStored(OFFLINE_NOTES_KEY,remaining);}
