function exportExcel(filename,sheetName,headers,rows){const xmlEsc=value=>String(value??"").replace(/[&<>]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;"}[char]));const tableRows=[headers,...rows].map((row,rowIndex)=>`<Row>${row.map(value=>`<Cell><Data ss:Type="String">${xmlEsc(value)}</Data></Cell>`).join("")}</Row>`).join("");const workbook=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="${xmlEsc(sheetName)}"><Table>${tableRows}</Table></Worksheet></Workbook>`;const blob=new Blob([workbook],{type:"application/vnd.ms-excel;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`${filename}.xls`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}

async function query(table, options = {}) {
  let q = db.from(table).select(options.select || "*");
  if (options.eq) Object.entries(options.eq).forEach(([k,v]) => q = q.eq(k,v));
  if (options.order) q = q.order(options.order, { ascending: options.ascending ?? true });
  const { data, error } = await q; if (error) throw error; return data;
}
async function mutate(promise, message) {
  const { error } = await promise; if (error) { toast(error.message, "error"); return false; }
  toast(message); return true;
}

function openModal(title, fields, onSubmit) {
  $("#modal-title").textContent = title;
  $("#modal-fields").innerHTML = fields;
  const form = $("#modal-form");
  if(title==="INCORPORAR PPL") form.querySelectorAll('input[name="primary_role"]').forEach(input=>input.required=false);
  form.querySelector('[type="submit"]').classList.remove("hidden");
  form.onsubmit = async event => { event.preventDefault(); const data=new FormData(form); if(title==="INCORPORAR PPL"&&!data.get("primary_role")&&!data.has("is_fajinero")){toast("SELECCIONÁ CURSANTE, MONITOR O FAJINERO.","error");return;} const button=form.querySelector('[type="submit"]'); button.disabled=true; try { if(await onSubmit(data)) $("#modal").close(); } finally { button.disabled=false; } };
  $("#modal").showModal();
}
function decorateActionButtons(){document.querySelectorAll("button").forEach(button=>{if(button.dataset.actionIcon)return;const label=button.textContent.trim();if(/^EDITAR\b/i.test(label)){button.dataset.actionIcon="edit";button.textContent=`✎ ${label}`;}else if(/^ELIMINAR\b/i.test(label)){button.dataset.actionIcon="delete";button.textContent=`🗑 ${label}`;}else if(button.id?.startsWith("export-")){button.dataset.actionIcon="spreadsheet";button.insertAdjacentHTML("afterbegin",moduleIcon("spreadsheet"));}else if(button.classList.contains("word-note-button")||button.id==="create-loan-pdf"){button.dataset.actionIcon="document";button.querySelector("span")?.remove();button.insertAdjacentHTML("afterbegin",moduleIcon("document"));}});}
new MutationObserver(decorateActionButtons).observe(document.body,{childList:true,subtree:true});
