async function renderPplLookup(){
  const saved=JSON.parse(sessionStorage.getItem("culture_ppl_lookup")||"null");
  content.innerHTML=`<a class="back button" href="#ppls">← VOLVER A PPLs</a>`+pageHead("Consulta institucional","Buscar PPL","Buscá por apellido, nombre o prontuario.","","search")+`<section class="panel"><form id="ppl-lookup-form" class="lookup-form"><label>Apellido<input name="last_name" autocomplete="off"></label><label>Nombre<input name="first_name" autocomplete="off"></label><label>Prontuario<input name="identifier" inputmode="numeric" data-numeric-only></label><div class="lookup-actions"><button class="primary">BUSCAR</button><button type="button" id="clear-ppl-lookup">LIMPIAR</button></div></form></section><section id="ppl-lookup-result" class="panel hidden"></section>`;
  const form=$("#ppl-lookup-form"),result=$("#ppl-lookup-result");
  const cleanIdentifier=value=>String(value||"").replace(/^0+(?=\d)/,"");
  const paint=rows=>{result.classList.remove("hidden");result.innerHTML=`<div class="panel-head"><div><h2>RESULTADOS</h2><small>${rows.length} COINCIDENCIA${rows.length===1?"":"S"}</small></div></div><table><thead><tr><th>Prontuario</th><th>Apellido</th><th>Nombre</th><th>Ubicación</th><th>Establecimiento</th><th>Estado</th><th></th></tr></thead><tbody>${rows.map((row,index)=>`<tr><td><code>${esc(cleanIdentifier(row.identifier)||"—")}</code></td><td>${esc(row.last_name||"—")}</td><td>${esc(row.first_name||"—")}</td><td>${esc(row.location||"—")}</td><td>${esc(row.establishment||"—")}</td><td>${esc(row.status||"—")}</td><td><button data-select-lookup="${index}">SELECCIONAR PPL</button></td></tr>`).join("")||empty("NO SE ENCONTRARON RESULTADOS.",7)}</tbody></table>`;document.querySelectorAll("[data-select-lookup]").forEach(button=>button.onclick=()=>openPplActivitySelector({...rows[Number(button.dataset.selectLookup)],identifier:cleanIdentifier(rows[Number(button.dataset.selectLookup)].identifier)}));};
  const searchWithBrowser=payload=>new Promise((resolve,reject)=>{const requestId=`ppl-${Date.now()}-${Math.random().toString(36).slice(2)}`;const finish=(error,rows)=>{window.removeEventListener("message",receive);clearTimeout(timeout);error?reject(new Error(error)):resolve(rows||[]);};const receive=event=>{const message=event.data||{};if(message.type!=="CULTURA_PPL_RESULT"||message.requestId!==requestId)return;finish(message.error,message.rows);};const timeout=setTimeout(()=>finish("NO SE DETECTÓ EL COMPLEMENTO DE BÚSQUEDA. INSTALALO Y VOLVÉ A INTENTAR."),120000);window.addEventListener("message",receive);window.postMessage({type:"CULTURA_PPL_SEARCH",requestId,payload},window.location.origin);});
  const uppercase=field=>field.value=field.value.toLocaleUpperCase("es-AR");
  [form.elements.last_name,form.elements.first_name].forEach(field=>field.addEventListener("input",()=>uppercase(field)));
  form.onsubmit=async event=>{event.preventDefault();if(!navigator.onLine){toast("LA BÚSQUEDA REQUIERE CONEXIÓN.","error");return;}const fields=new FormData(form),identifier=String(fields.get("identifier")||"").trim(),last=String(fields.get("last_name")||"").trim()||"%",first=String(fields.get("first_name")||"").trim()||"%";result.classList.remove("hidden");result.innerHTML='<div class="loading">BUSCANDO EN EL SISTEMA INSTITUCIONAL…</div>';try{const rows=await searchWithBrowser({last_name:last,first_name:first,identifier});sessionStorage.setItem("culture_ppl_lookup",JSON.stringify({last_name:form.elements.last_name.value,first_name:form.elements.first_name.value,identifier,rows}));paint(rows);}catch(error){result.classList.remove("hidden");result.innerHTML=`<div class="error-card"><h2>NO SE PUDO REALIZAR LA BÚSQUEDA</h2><p>${esc(error.message)}</p></div>`;}};
  $("#clear-ppl-lookup").onclick=()=>{form.reset();sessionStorage.removeItem("culture_ppl_lookup");result.classList.add("hidden");};
  if(saved){form.elements.last_name.value=saved.last_name||"";form.elements.first_name.value=saved.first_name||"";form.elements.identifier.value=saved.identifier||"";paint(Array.isArray(saved.rows)?saved.rows:[]);}
}

