  const load=()=>loadAttendance(Number($("#attendance-workshop").value),$("#attendance-date").value); $("#attendance-workshop").onchange=load; $("#attendance-date").onchange=load; if(selected)load(); else $("#attendance-list").innerHTML='<div class="empty-card">Primero creá un taller.</div>';
