async function loadAttendance(workshopId,date) {
  const target=$("#attendance-list");target.innerHTML='<div class="loading">Cargando…</div>';
  const {data:enrolled,error}=await db.from("enrollments").select("id,people(*)").eq("workshop_id",workshopId).eq("active",true);if(error)throw error;
  const records=await query("attendance",{eq:{workshop_id:workshopId,attendance_date:date}});const map=new Map(records.map(r=>[r.enrollment_id,r]));
  target.innerHTML=`<form id="attendance-form"><section class="panel"><table><thead><tr><th>Cursante</th><th>Prontuario</th><th>Estado</th></tr></thead><tbody>${enrolled.map(e=>`<tr><td><strong>${esc(e.people.last_name)}, ${esc(e.people.first_name)}</strong></td><td>${esc(e.people.identifier)}</td><td><select name="status_${e.id}"><option ${map.get(e.id)?.status==="presente"?"selected":""}>presente</option><option ${map.get(e.id)?.status==="ausente"?"selected":""}>ausente</option><option ${map.get(e.id)?.status==="justificado"?"selected":""}>justificado</option></select></td></tr>`).join("")||empty("NO HAY CURSANTES INSCRIPTOS.",3)}</tbody></table></section>${enrolled.length?`<div class="save-bar"><span>${enrolled.length} CURSANTES</span><button class="primary">Guardar asistencia</button></div>`:""}</form>`;
  if(enrolled.length) $("#attendance-form").onsubmit=async e=>{e.preventDefault();const rows=enrolled.map(item=>({workshop_id:workshopId,enrollment_id:item.id,attendance_date:date,status:new FormData(e.target).get(`status_${item.id}`),registered_by:state.session.user.id}));const ok=await mutate(db.from("attendance").upsert(rows,{onConflict:"enrollment_id,attendance_date"}),"Asistencia guardada.");if(ok)loadAttendance(workshopId,date);};
}

async function renderActivities() {
  loading();
  const activities = await
    db.from("activities").select("*,activity_schedules(day_of_week,start_time,end_time),activity_participants(people(*))").eq("archived",false).order("created_at", { ascending:false }).then(r=>{if(r.error)throw r.error;return r.data});
  const activityActions=`<div class="head-actions"><a class="button activity-history-button" href="#attendance">${moduleIcon("archive")}<span>ASISTENCIA HISTÓRICO</span></a>${canManageActivities()?'<button id="new-activity" class="primary">+ NUEVA ACTIVIDAD</button>':""}</div>`;
  content.innerHTML=pageHead("Agenda cultural","Actividades","Las jornadas están agrupadas por nombre de actividad.",activityActions)+`<section class="global-search"><label>BUSCAR INTEGRANTE<input id="activity-participant-search" type="search" placeholder="Escribí un prontuario, nombre o apellido…"></label></section><div id="activity-participant-results" class="hidden"></div><div id="activity-cards">${activityGroupTable(activities,"NO HAY ACTIVIDADES PARA MOSTRAR.")}</div>`;
  const paintSearchResults=()=>{const term=normalizeFilter($("#activity-participant-search").value),container=$("#activity-participant-results");if(!term){container.classList.add("hidden");container.innerHTML="";return;}const matches=[];activities.forEach(activity=>{const schedule=activity.activity_schedules?.[0]||{};(activity.activity_participants||[]).forEach(entry=>{const person=entry.people||{};if([person.identifier,person.first_name,person.last_name,`${person.last_name||""} ${person.first_name||""}`].some(value=>normalizeFilter(value).includes(term)))matches.push({person,activity,schedule});});});matches.sort((a,b)=>String(a.person.last_name||"").localeCompare(String(b.person.last_name||""),"es")||String(a.person.first_name||"").localeCompare(String(b.person.first_name||""),"es"));container.classList.remove("hidden");container.innerHTML=`<section class="panel activity-search-panel"><div class="panel-head"><div><h2>RESULTADOS DE INTEGRANTES</h2><small>${matches.length} COINCIDENCIAS</small></div></div><table><thead><tr><th>Apellido y nombre</th><th>Prontuario</th><th>Actividad</th><th>Día</th><th>Horario</th></tr></thead><tbody>${matches.map(item=>`<tr><td><strong>${esc(item.person.last_name)}, ${esc(item.person.first_name)}</strong></td><td><code>${esc(item.person.identifier)}</code></td><td>${esc(item.activity.title)}</td><td>${esc(item.schedule.day_of_week||"—")}</td><td>${item.schedule.start_time?`${esc(String(item.schedule.start_time).slice(0,5))}–${esc(String(item.schedule.end_time||item.schedule.start_time).slice(0,5))}`:"—"}</td></tr>`).join("")||empty("NO SE ENCONTRARON INTEGRANTES.",5)}</tbody></table></section>`;};
  if($("#new-activity")) $("#new-activity").onclick=async()=>openActivityEditor(null,await loadActiveMonitors());
  document.querySelectorAll("[data-activity-group]").forEach(button=>button.onclick=()=>{sessionStorage.setItem("culture_activity_group",button.dataset.activityGroup);location.hash="activity-group";});
  $("#activity-participant-search").addEventListener("input",paintSearchResults);
}

function groupActivities(items){const groups=new Map();items.forEach(item=>{const key=item.title||"SIN NOMBRE",group=groups.get(key)||{title:key,items:[]};group.items.push(item);groups.set(key,group);});return [...groups.values()].sort((a,b)=>a.title.localeCompare(b.title,"es"));}
function activityGroupTable(items,emptyText){const groups=groupActivities(items);return `<section class="activity-section"><div class="activity-section-head"><h2>ACTIVIDADES</h2><span class="badge">${groups.length}</span></div><div class="activity-card-grid">${groups.map(group=>{const schedules=group.items.flatMap(item=>item.activity_schedules||[]),people=new Set(group.items.flatMap(item=>(item.activity_participants||[]).map(entry=>entry.people?.id).filter(Boolean))),hasActive=group.items.some(item=>item.status==="activa"),color=activityColorKey(group.title);return `<article class="activity-card activity-color-${color} ${hasActive?"":"finished"}"><div class="activity-card-top"><span class="activity-card-icon">${moduleIcon(activityIconKey(group.title))}</span>${badge(hasActive?"ACTIVA":"FINALIZADA")}</div><h2>${esc(group.title)}</h2><dl><div><dt>Jornadas</dt><dd>${group.items.length}</dd></div><div><dt>Integrantes</dt><dd>${people.size}</dd></div></dl><div class="activity-schedules">${formatSchedules(schedules)}</div><div class="activity-card-actions"><button class="primary" data-activity-group="${esc(group.title)}">INGRESAR</button></div></article>`;}).join("")||`<div class="empty-card">${esc(emptyText)}</div>`}</div></section>`;}

async function loadActiveMonitors(){return db.from("area_people").select("id,identifier,last_name,first_name").eq("is_monitor",true).eq("active",true).is("deleted_at",null).order("last_name").then(r=>{if(r.error)throw r.error;return r.data});}

async function renderActivityGroup(){
  const title=sessionStorage.getItem("culture_activity_group");if(!title){location.hash="activities";return;}
  loading();const [activities,monitors]=await Promise.all([db.from("activities").select("*,activity_schedules(day_of_week,start_time,end_time),activity_participants(people(*))").eq("title",title).eq("archived",false).order("created_at",{ascending:false}).then(r=>{if(r.error)throw r.error;return r.data}),loadActiveMonitors()]);
  activities.sort((a,b)=>{const first=a.activity_schedules?.[0]||{},second=b.activity_schedules?.[0]||{};return WEEKDAYS.indexOf(first.day_of_week)-WEEKDAYS.indexOf(second.day_of_week)||String(first.start_time||"").localeCompare(String(second.start_time||""));});
  const groupAction=canManageActivities()?'<button id="new-group-session" class="primary">+ AGREGAR DÍA Y GRUPO</button>':"";
  content.innerHTML=`<a class="back button" href="#activities">← VOLVER A ACTIVIDADES</a>`+pageHead("Actividad agrupada",esc(title),canManageActivities()?"Administrá por separado cada día, horario e integrantes.":"Consultá las jornadas e ingresá a registrar asistencia desde el Calendario.",groupAction,activityIconKey(title))+`<section class="activity-instance-list">${activities.map(a=>`<article class="activity-instance ${a.status==="finalizada"?"finished":""}"><div><span>${badge(a.status)}</span><h2>${formatSchedules(a.activity_schedules)}</h2><p><strong>${esc(a.location||"SIN LUGAR")}</strong> · MONITOR: ${esc(a.instructor||"SIN ASIGNAR")}</p><small>${a.activity_participants?.length||0} INTEGRANTES</small></div><div class="row-actions"><button data-open-activity="${a.id}">VER INTEGRANTES</button>${canManageActivities()?`<button data-edit-activity="${a.id}">EDITAR</button>${a.status==="activa"?`<button data-finish-activity="${a.id}">FINALIZAR</button>`:`<button data-archive-activity="${a.id}">ARCHIVAR</button>`}`:""}</div></article>`).join("")||'<div class="empty-card">NO HAY JORNADAS ACTIVAS PARA ESTA ACTIVIDAD.</div>'}</section>`;
  if($("#new-group-session")) $("#new-group-session").onclick=()=>openActivityEditor(null,monitors,title);
  document.querySelectorAll("[data-open-activity]").forEach(button=>button.onclick=()=>activityDetail(Number(button.dataset.openActivity)));
  if(canManageActivities())document.querySelectorAll("[data-edit-activity]").forEach(button=>button.onclick=()=>openActivityEditor(activities.find(item=>item.id===Number(button.dataset.editActivity)),monitors));
  document.querySelectorAll("[data-finish-activity]").forEach(button=>button.onclick=async()=>{if(!confirm("¿FINALIZAR ESTA JORNADA?"))return;const ok=await mutate(db.from("activities").update({status:"finalizada"}).eq("id",Number(button.dataset.finishActivity)),"JORNADA FINALIZADA.");if(ok)renderActivityGroup();});
  document.querySelectorAll("[data-archive-activity]").forEach(button=>button.onclick=async()=>{if(!confirm("¿ENVIAR ESTA JORNADA AL ARCHIVO?"))return;const ok=await mutate(db.from("activities").update({archived:true,archived_at:new Date().toISOString()}).eq("id",Number(button.dataset.archiveActivity)),"JORNADA ARCHIVADA.");if(ok)renderActivityGroup();});
}

function openActivityEditor(activity,monitors,presetTitle=null){
  const editing=Boolean(activity),selectedTitle=activity?.title||presetTitle||"",schedule=activity?.activity_schedules?.[0]||{},participants=activity?.activity_participants?.length?activity.activity_participants.map(item=>item.people):[{}];
  const monitorNames=monitors.map(item=>`${item.last_name}, ${item.first_name}`),legacyInstructor=activity?.instructor&&!monitorNames.includes(activity.instructor)?`<option value="${esc(activity.instructor)}" selected>${esc(activity.instructor)} · MONITOR ACTUAL</option>`:"";
  const instructorOptions=legacyInstructor+monitors.map(item=>{const name=`${item.last_name}, ${item.first_name}`;return `<option value="${esc(name)}" ${name===activity?.instructor?"selected":""}>${esc(name)} · ${esc(item.identifier)}</option>`;}).join("");
  const titleField=presetTitle&&!editing?`<label class="full">Actividad<input type="text" value="${esc(selectedTitle)}" disabled><input type="hidden" name="title" value="${esc(selectedTitle)}"></label>`:`<label class="full">Actividad<select name="title" required>${activityTypeOptions(selectedTitle)}</select></label>`;
  openModal(editing?"EDITAR ACTIVIDAD":"NUEVA ACTIVIDAD",`${titleField}<label class="full">Monitor<select name="instructor"><option value="">SIN MONITOR ASIGNADO</option>${instructorOptions}</select></label><label class="full">Lugar<select name="location" required>${activityPlaceOptions(activity?.location)}</select></label><div class="full schedule-builder"><div class="schedule-title"><strong>DÍA Y HORARIO</strong><small>UNA ACTIVIDAD CORRESPONDE A UNA ÚNICA JORNADA SEMANAL</small></div><div class="schedule-row single-schedule"><select name="schedule_day" required>${weekdayOptions(schedule.day_of_week)}</select><select name="schedule_start_time" required>${workshopTimeOptions(String(schedule.start_time||"").slice(0,5))}</select><select name="schedule_end_time" required>${endTimeOptions(String(schedule.end_time||"").slice(0,5))}</select></div></div><div class="full participant-builder"><div class="schedule-title"><div><strong>INTEGRANTES DE LA ACTIVIDAD</strong><small>EL CUPO SE FORMA CON LAS PPLs CARGADAS AQUÍ</small></div><button type="button" id="add-participant">+ AGREGAR PPL</button></div><div id="participant-rows">${participants.map(activityParticipantRow).join("")}</div></div><label class="full">Descripción<textarea name="description">${esc(activity?.description||"")}</textarea></label>`,async f=>{
    const v=upperObject(f),newSchedules=[{day_of_week:f.get("schedule_day"),start_time:f.get("schedule_start_time"),end_time:f.get("schedule_end_time")}];
    const identifiers=f.getAll("participant_identifier"),lastNames=f.getAll("participant_last_name"),firstNames=f.getAll("participant_first_name"),locations=f.getAll("participant_location");
    const newParticipants=identifiers.map((identifier,index)=>({identifier,last_name:lastNames[index],first_name:firstNames[index],location:locations[index]}));
    if(newSchedules.some(item=>item.end_time<=item.start_time)){toast("LA HORA DE FINALIZACIÓN DEBE SER POSTERIOR A LA DE COMIENZO.","error");return false;}
    if(new Set(identifiers).size!==identifiers.length){toast("NO PODÉS CARGAR DOS VECES EL MISMO PRONTUARIO.","error");return false;}
    const rpc=editing?"update_cultural_activity":"create_cultural_activity",payload={p_title:v.title,p_instructor:v.instructor||null,p_capacity:null,p_location:v.location,p_description:v.description||null,p_schedules:newSchedules,p_participants:newParticipants};if(editing)payload.p_activity_id=activity.id;
    const {error}=await db.rpc(rpc,payload);if(error){toast(error.message,"error");return false;}toast(editing?"ACTIVIDAD ACTUALIZADA.":"ACTIVIDAD CREADA.");if(location.hash==="#activity-group"){sessionStorage.setItem("culture_activity_group",v.title);renderActivityGroup();}else if(location.hash==="#calendar")renderCalendar();else renderActivities();return true;
  });
  const participantRows=$("#participant-rows"),syncParticipantButtons=()=>document.querySelectorAll(".remove-activity-participant").forEach(button=>button.onclick=()=>button.closest(".activity-participant-row").remove());
  $("#add-participant").onclick=()=>{participantRows.insertAdjacentHTML("beforeend",activityParticipantRow());syncParticipantButtons();};syncParticipantButtons();
}

function activityParticipantRow(person={}){return `<div class="activity-participant-row"><input type="text" name="participant_identifier" value="${esc(person.identifier||"")}" placeholder="PRONTUARIO" inputmode="numeric" pattern="[0-9]+" data-numeric-only required><input type="text" name="participant_last_name" value="${esc(person.last_name||"")}" placeholder="APELLIDO" required><input type="text" name="participant_first_name" value="${esc(person.first_name||"")}" placeholder="NOMBRE" required><select name="participant_location" required>${locationOptions(person.location)}</select><button type="button" class="danger remove-activity-participant" aria-label="Quitar integrante">×</button></div>`;}

