function calendarEvent(item,date,compact=false,journey=null){const activity=item.activities||{},color=activityColorKey(activity.title),cancelled=Boolean(journey?.cancelled),endTime=String(item.end_time||item.start_time||"00:00").slice(0,5),past=date<today()||(date===today()&&new Date(`${date}T${endTime}:00`)<=new Date());return `<article class="calendar-event activity-color-${color} ${compact?"compact":""} ${cancelled?"cancelled":""} ${past?"past":""}"><button class="calendar-attendance" data-calendar-activity="${activity.id}" data-calendar-date="${date}"><time>${cancelled?"⚠ ":""}${esc(String(item.start_time).slice(0,5))}–${esc(endTime)}</time><strong>${cancelled?"JORNADA CANCELADA · ":""}${esc(activity.title||"ACTIVIDAD")}</strong>${cancelled?`<small>${esc(journey.cancellation_reason||"")}</small>`:compact?"":`<small>${esc(activity.location||"")}</small>`}</button>${canManageActivities()?`<button class="calendar-edit" data-calendar-edit="${activity.id}" aria-label="Editar ${esc(activity.title||"actividad")}" title="EDITAR ACTIVIDAD">✎</button>`:""}</article>`;}
function bindCalendarEvents(){document.querySelectorAll("[data-calendar-activity]").forEach(button=>button.onclick=()=>{sessionStorage.setItem("calendar_activity",button.dataset.calendarActivity);sessionStorage.setItem("calendar_date",button.dataset.calendarDate);sessionStorage.setItem("attendance_source","calendar");sessionStorage.setItem("attendance_readonly","false");location.hash="activity-attendance";});if(canManageActivities())document.querySelectorAll("[data-calendar-edit]").forEach(button=>button.onclick=()=>editActivityFromCalendar(Number(button.dataset.calendarEdit)));}
