async function loadParticipantRemovalTickets(){
  const result=await db.from("participant_removal_tickets").select("*").order("created_at",{ascending:false});
  if(!result.error)return {rows:result.data||[],available:true};
  const message=String(result.error.message||"").toLowerCase();
  if(result.error.code==="PGRST205"||message.includes("participant_removal_tickets")&&message.includes("schema cache"))return {rows:[],available:false};
  throw result.error;
}

