function loanNoteHtml(loan){const date=new Date(`${loan.received_at||today()}T12:00:00`),dateText=date.toLocaleDateString("es-AR",{day:"numeric",month:"long",year:"numeric"}),ppl=String(loan.ppl_name||"").toLocaleUpperCase("es-AR"),instrument=String(loan.instrument_name||"").toLocaleUpperCase("es-AR"),observations=String(loan.observations||"SIN OBSERVACIONES").toLocaleUpperCase("es-AR");return `<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Acta de entrega</title><style>@page{size:A4;margin:25mm}body{font-family:"Times New Roman",serif;color:#111;font-size:14pt;line-height:1.9}h1{text-align:center;font-size:16pt;margin:0 0 60px}.date{text-align:right;margin-bottom:62px}.body{text-align:justify}.body p{text-indent:3.5em;margin:0 0 22px}.firmas{display:flex;justify-content:space-between;margin-top:95px;text-align:center}.firma{width:39%;border-top:1px solid #111;padding-top:9px;font-size:12pt}@media print{body{font-size:13pt}}</style></head><body><h1>ACTA DE ENTREGA</h1><p class="date">Mendoza, ${dateText}.</p><div class="body"><p>En la provincia de Mendoza, departamento de Luján de Cuyo, localidad de Cacheuta, Complejo Penitenciario de Alojamiento Permanente “Almafuerte”, la Oficina de Promoción Cultural hace entrega a la P.P.L. <strong>${esc(ppl)}</strong>, de los siguientes elementos: <strong>cantidad (01) ${esc(instrument)} y ${esc(observations)}.</strong></p><p>La P.P.L. mencionada se compromete a devolverlos una vez finalizada su uso, en las mismas condiciones en que fueron prestados.</p><p>Sin más que agregar, se da por finalizado el presente acto, de conformidad ante los funcionarios de <strong>Promoción Cultural.</strong></p></div><div class="firmas"><div class="firma">Firma de la PPL</div><div class="firma">Firma del efectivo</div></div><script>window.onload=()=>window.print()<\/script></body></html>`;}
