const filtered=()=>{const search=normalizeFilter($("#map-filter-search").value),location=$("#map-filter-location").value,activity=$("#map-filter-activity").value;return activeRecords.filter(item=>{const matchesLocation=!location||location==="TODOS"?true:location==="TODOS LOS MÓDULOS"?String(item.people.location||"").startsWith("MÓDULO "):item.people.location===location;return(!search||[item.people.identifier,item.people.first_name,item.people.last_name].some(value=>normalizeFilter(value).includes(search)))&&matchesLocation&&(!activity||item.activities.title===activity);});};
  const renderSearchResults=()=>{const rows=filtered(),people=new Map();rows.forEach(item=>{const current=people.get(item.people.id)||{...item.people,activities:[]};if(!current.activities.includes(item.activities.title))current.activities.push(item.activities.title);people.set(item.people.id,current);});const results=[...people.values()].sort((a,b)=>String(a.last_name||"").localeCompare(String(b.last_name||""),"es")||String(a.first_name||"").localeCompare(String(b.first_name||""),"es")),panel=$("#map-search-results");panel.classList.remove("hidden");panel.innerHTML=`<div class="panel-head"><div><h2>RESULTADOS DE BÚSQUEDA</h2><small>${results.length} PPLs QUE COINCIDEN CON LOS FILTROS</small></div></div><table><thead><tr><th>Prontuario</th><th>Apellido y nombre</th><th>Ubicación</th><th>Actividades activas</th></tr></thead><tbody>${results.map(person=>`<tr><td><code>${esc(person.identifier)}</code></td><td><strong>${esc(person.last_name)}, ${esc(person.first_name)}</strong></td><td>${esc(person.location||"—")}</td><td>${person.activities.map(esc).join(" · ")||"—"}</td></tr>`).join("")||empty("NO HAY PPLs QUE COINCIDAN CON LOS FILTROS.",4)}</tbody></table>`;};
  $("#toggle-map-filters").onclick=()=>{const panel=$("#map-filters"),open=panel.classList.toggle("hidden")===false;$("#toggle-map-filters").setAttribute("aria-expanded",String(open));};$("#clear-map-filters").onclick=()=>{document.querySelectorAll("#map-filters input,#map-filters select").forEach(field=>field.value="");$("#map-search-results").classList.add("hidden");$("#map-search-results").innerHTML="";};$("#search-map-filters").onclick=renderSearchResults;$("#export-map").onclick=()=>exportExcel("MAPA_PROMOCION_CULTURAL","MAPA",["PRONTUARIO","APELLIDO","NOMBRE","UBICACIÓN","ACTIVIDAD"],filtered().map(item=>[item.people.identifier,item.people.last_name,item.people.first_name,item.people.location,item.activities.title]));
  document.querySelectorAll("[data-map-location]").forEach(button=>button.onclick=()=>{document.querySelectorAll(".map-wing").forEach(item=>item.classList.remove("selected"));button.classList.add("selected");renderMapWingDetail(button.dataset.mapLocation,activeRecords);});
